// v0.18.59-field-definition-caption-in-detail-header
// Generated by responsibility split. No functional change intended.

// v0.18.40-studio-editor-component-model:
// Detail Editor is a generic Component Host.
// It reads ViewDef-declared editorComponents and delegates creation/lifecycle to the common Host / Registry.
let detailEditorComponentHost = null;
let detailEditorComponentSlotsCache = null;

function detailEditorComponentConfigs(gd) {
  const raw = gd?.editorComponents ?? gd?.editor_components ?? [];
  return Array.isArray(raw) ? raw : [];
}

function detailEditorComponentSlots() {
  const cached = detailEditorComponentSlotsCache;
  if (
    cached?.detailHeader?.isConnected &&
    cached?.detailBody?.isConnected &&
    cached?.afterChildGrids?.isConnected &&
    cached?.detailFooter?.isConnected
  ) return cached;

  detailEditorComponentSlotsCache = {
    detailHeader: $('detailComponentHeaderArea'),
    detailBody: $('detailComponentBodyArea'),
    afterChildGrids: $('detailComponentAfterChildArea'),
    detailFooter: $('detailComponentFooterArea')
  };
  return detailEditorComponentSlotsCache;
}

function currentDetailEditorComponentContext(row, gd) {
  return {
    row,
    rowIndex: selectedIndex,
    mode: detailMode,
    viewDef,
    gridDef: gd,
    sourceData
  };
}

function ensureDetailEditorComponentHost() {
  if (typeof EditorComponentHost === 'undefined') return null;

  if (!detailEditorComponentHost) {
    detailEditorComponentHost = new EditorComponentHost();
  }

  const dialog = $('detailDialog');
  if (dialog && dialog.dataset.editorComponentHostCloseBound !== 'true') {
    dialog.dataset.editorComponentHostCloseBound = 'true';
    dialog.addEventListener('close', () => {
      detailEditorComponentHost?.destroy();
    });
  }

  return detailEditorComponentHost;
}

function renderDetailEditorComponents(row, gd) {
  const host = ensureDetailEditorComponentHost();
  if (!host) return;

  host.sync(
    detailEditorComponentConfigs(gd),
    detailEditorComponentSlots(),
    currentDetailEditorComponentContext(row, gd)
  );
}

function detailFieldSetConfigs(gd) {
  const raw = gd?.fieldSets ?? gd?.field_sets ?? [];
  return Array.isArray(raw) ? raw.filter(item => item && typeof item === 'object') : [];
}

function detailFieldSetFieldNames(fieldSet) {
  const raw = fieldSet?.fields ?? [];
  if (!Array.isArray(raw)) return [];
  const seen = new Set();
  return raw
    .map(value => String(value ?? '').trim())
    .filter(value => value && !seen.has(value) && seen.add(value));
}

function createDetailFieldSet(fieldSet, fields, row, gd) {
  const group = document.createElement('fieldset');
  const caption = String(fieldSet?.caption ?? '').trim();
  group.className = 'detail-fieldset' + (caption ? '' : ' detail-fieldset-captionless');
  if (fieldSet?.id) group.dataset.fieldSetId = String(fieldSet.id);

  // v0.18.52-detail-fieldset-cross-field-ux:
  // caption is optional by contract. Do not render an empty legend because the empty
  // notch/spacing itself would become redundant UI noise.
  if (caption) {
    const legend = document.createElement('legend');
    legend.textContent = caption;
    group.appendChild(legend);
  }

  const grid = document.createElement('div');
  grid.className = 'detail-fieldset-grid';
  fields.forEach(field => {
    grid.appendChild(createInput(field, getByPath(row, field.field), 'detail', false, row, gd));
  });
  group.appendChild(grid);
  return group;
}

function renderDetailBodyFields(form, row, gd) {
  const fields = detailVisibleFields(gd, row).filter(field => !isDetailFooterField(field));
  const fieldByName = new Map(fields.map(field => [String(field.field), field]));
  const fieldSetByField = new Map();
  const configs = detailFieldSetConfigs(gd);

  configs.forEach(fieldSet => {
    detailFieldSetFieldNames(fieldSet).forEach(fieldName => {
      // First declaration wins. A Field cannot be rendered into two visual groups.
      if (fieldByName.has(fieldName) && !fieldSetByField.has(fieldName)) {
        fieldSetByField.set(fieldName, fieldSet);
      }
    });
  });

  const renderedSets = new Set();
  fields.forEach(field => {
    const fieldSet = fieldSetByField.get(String(field.field));
    if (!fieldSet) {
      form.appendChild(createInput(field, getByPath(row, field.field), 'detail', false, row, gd));
      return;
    }
    if (renderedSets.has(fieldSet)) return;

    const groupedFields = detailFieldSetFieldNames(fieldSet)
      .map(fieldName => fieldByName.get(fieldName))
      .filter(Boolean);
    if (groupedFields.length) form.appendChild(createDetailFieldSet(fieldSet, groupedFields, row, gd));
    renderedSets.add(fieldSet);
  });
}

function renderDetailForRow(row) {
  if (typeof clearStudioJsonRoundTripDiff === 'function') clearStudioJsonRoundTripDiff();
  const gd = gridDef();
  const pasteBtn = $('pasteCopiedBtn');
  if (pasteBtn) pasteBtn.disabled = !copiedRow;
  const form = $('detailForm');
  form.innerHTML = '';

  if (typeof renderTargetContextDetailPanel === 'function') renderTargetContextDetailPanel(row, gd, form);

  renderDetailBodyFields(form, row, gd);

  renderChildArea(row, gd);
  renderDetailFooterFields(row, gd);
  renderDetailEditorComponents(row, gd);
  updateDetailNavButtons();
}

function rebindDetailAfterCanonicalCommit(row, { preserveScroll=true }={}) {
  const body = $('detailDialog')?.querySelector?.('.dialog-body') ?? null;
  const scrollTop = preserveScroll ? Number(body?.scrollTop ?? 0) : 0;
  renderDetailForRow(row);
  if (preserveScroll && body) {
    const restore = () => { body.scrollTop = scrollTop; };
    if (typeof requestAnimationFrame === 'function') requestAnimationFrame(restore);
    else restore();
  }
}

function openDetail(index, keepOpen=false) {
  if (typeof discardStudioJsonRoundTripDraft === 'function') discardStudioJsonRoundTripDraft();
  detailMode = 'edit';
  draftRow = null;
  selectedIndex = index;
  const row = currentRows[index];
  renderDetailForRow(row);
  if (!keepOpen || !$('detailDialog').open) $('detailDialog').showModal();
}

function openNewDetail(row, statusMessage='新規登録画面を開きました') {
  if (typeof discardStudioJsonRoundTripDraft === 'function') discardStudioJsonRoundTripDraft();
  detailMode = 'new';
  draftRow = row;
  selectedIndex = -1;
  renderGrid();
  renderDetailForRow(draftRow);
  setStatus(statusMessage);
  if (!$('detailDialog').open) $('detailDialog').showModal();
}
function renderChildArea(row, gd) {
  const area = $('childArea');
  area.innerHTML = '';
  gd.fields
    .filter(f => (f.type === 'objectArray' || f.type === 'stringArray') && !(typeof isTargetContextField === 'function' && isTargetContextField(f)))
    .filter(f => typeof isFieldVisibleInDetail === 'function'
      ? isFieldVisibleInDetail(f, row)
      : (f?.edit?.visible !== false && (typeof fieldMatchesVisibleWhen === 'function' ? fieldMatchesVisibleWhen(f, row) : true)))
    .forEach(field => {
    const data = getByPath(row, field.field);
    if (!Array.isArray(data)) return;

    // v0.16.2-detail-subgrid-table-edit-core-mvp:
    // objectArray / stringArray は、表示専用tableから編集可能なStudio標準サブグリッドMVPへ委譲する。
    // Runtimeはoutputs/success_conditions等の固定フィールド名ではなく、ViewDefのfield.typeを見て扱う。
    if (typeof createDetailSubGridCard === 'function') {
      area.appendChild(createDetailSubGridCard({ field, row, gd, data }));
      return;
    }

    const card = document.createElement('div');
    card.className = 'child-card';
    const title = document.createElement('h3');
    title.textContent = field.caption ?? field.field;
    card.appendChild(title);
    const wrap = document.createElement('div');
    wrap.className = 'child-table-wrap';
    const table = document.createElement('table');
    if (field.type === 'stringArray') {
      table.innerHTML = '<thead><tr><th>#</th><th>value</th></tr></thead>';
      const tb = document.createElement('tbody');
      data.forEach((v, i) => {
        const tr = document.createElement('tr');
        tr.innerHTML = `<td>${i+1}</td><td>${formatValue(v)}</td>`;
        tb.appendChild(tr);
      });
      table.appendChild(tb);
    } else {
      const keys = [...new Set(data.flatMap(o => Object.keys(o ?? {})))];
      const thead = document.createElement('thead');
      const trh = document.createElement('tr');
      keys.forEach(k => { const th = document.createElement('th'); th.textContent = k; trh.appendChild(th); });
      thead.appendChild(trh); table.appendChild(thead);
      const tb = document.createElement('tbody');
      data.forEach(o => {
        const tr = document.createElement('tr');
        keys.forEach(k => { const td = document.createElement('td'); td.textContent = formatValue(o?.[k]); tr.appendChild(td); });
        tb.appendChild(tr);
      });
      table.appendChild(tb);
    }
    wrap.appendChild(table); card.appendChild(wrap); area.appendChild(card);
  });
}

// Round Trip compatibility: consumeStudioJsonRoundTripDraft must not run before Runtime Validation;
// the pending draft is staged with getStudioJsonRoundTripDraftRow and cleared only after an accepted commit.
function buildPendingDetailApplyRow(baseRow) {
  if (!baseRow) return null;
  const roundTripDraft = typeof getStudioJsonRoundTripDraftRow === 'function'
    ? getStudioJsonRoundTripDraftRow()
    : null;
  const working = cloneData(roundTripDraft ?? baseRow) ?? {};
  // F12 validation must inspect the latest UI values without mutating canonical Data.
  // SubGrid dirty state is only cleared after validation succeeds.
  applyDetailInputsToRow(working, { markSubGridCommitted: false });
  return working;
}

function clearRuntimeFieldDefinitionValidationMarks() {
  const root = $('detailDialog') ?? document;
  root?.querySelectorAll?.('.studio-field-definition-invalid').forEach(el => {
    el.classList.remove('studio-field-definition-invalid');
  });
}

function markRuntimeFieldDefinitionValidationErrors(result) {
  const root = $('detailDialog') ?? document;
  const checks = Array.isArray(result?.blocking_checks) ? result.blocking_checks : [];
  checks.forEach(check => {
    const fieldName = String(check?.field_name ?? '');
    if (!fieldName) return;
    const escaped = globalThis.CSS?.escape ? CSS.escape(fieldName) : fieldName.replace(/["\\]/g, '\\$&');
    root?.querySelectorAll?.(`[data-field="${escaped}"]`).forEach(control => {
      const target = control.closest?.('.field') ?? control;
      target.classList?.add?.('studio-field-definition-invalid');
    });
  });
}

function validatePendingDetailApplyRow(row, gd) {
  if (typeof RuntimeFieldDefinitionValidationService === 'undefined') {
    return { status: 'SKIPPED', reason_code: 'RUNTIME_VALIDATION_SERVICE_UNAVAILABLE', checks: [], blocking_checks: [] };
  }
  const service = new RuntimeFieldDefinitionValidationService();
  return service.validateRow({
    row,
    gridDef: gd,
    fieldDefinitionDocument: currentRuntimeFieldDefinitionDocument,
    registry: currentRuntimeValidationTypeRegistry
  });
}

function reportRuntimeFieldDefinitionValidationFailure(result) {
  clearRuntimeFieldDefinitionValidationMarks();
  markRuntimeFieldDefinitionValidationErrors(result);
  const detailText = typeof formatRuntimeFieldDefinitionValidationDetail === 'function'
    ? formatRuntimeFieldDefinitionValidationDetail(result)
    : String(result?.reason_code ?? 'FIELD_DEFINITION_CONTRACT_VIOLATION');

  const count = Array.isArray(result?.blocking_checks) ? result.blocking_checks.length : 0;
  setStatus(`F12反映を拒否しました: Field Definition契約違反 ${count}件`, {
    kind: 'error',
    title: 'Field Definition契約違反',
    toast: false,
    sticky: true
  });
  if (typeof showStudioConfirmDialog === 'function') {
    showStudioConfirmDialog({
      title: 'Field Definition契約違反',
      message: '入力値がField Definitionの契約を満たしていないため、正本Dataへ反映しませんでした。入力値は画面に残しています。',
      detail: detailText,
      okText: '閉じる',
      cancelText: '戻る',
      danger: true
    });
  }
}

function replaceDetailRowPreservingReferences(rows, index, nextRow) {
  if (!Array.isArray(rows) || index < 0 || index >= rows.length) return nextRow;
  const current = rows[index];

  // v0.18.60-detail-grid-immediate:
  // filteredRows は canonical row object への参照を保持している。
  // F12で rows[index] 自体を差し替えるとGrid側だけ古いobjectを掴み続けるため、
  // 通常object rowは同一identityのまま内容だけ置換して即時反映させる。
  if (
    current && nextRow &&
    typeof current === 'object' && !Array.isArray(current) &&
    typeof nextRow === 'object' && !Array.isArray(nextRow)
  ) {
    Object.keys(current).forEach(key => { delete current[key]; });
    Object.keys(nextRow).forEach(key => { current[key] = nextRow[key]; });
    return current;
  }

  rows[index] = nextRow;
  return nextRow;
}

function finalizeValidatedDetailCommit(row, index) {
  replaceDetailRowPreservingReferences(currentRows, index, row);
  if (typeof getStudioJsonRoundTripDraftRow === 'function' && getStudioJsonRoundTripDraftRow()) {
    if (typeof discardStudioJsonRoundTripDraft === 'function') discardStudioJsonRoundTripDraft();
  }
  if (typeof markDetailSubGridEditsCommitted === 'function') markDetailSubGridEditsCommitted();
  clearRuntimeFieldDefinitionValidationMarks();
}

function tryCommitCurrentDetailEdits(options={}) {
  if (detailMode !== 'edit' || selectedIndex < 0 || !currentRows[selectedIndex]) return true;
  const gd = gridDef();
  const pending = buildPendingDetailApplyRow(currentRows[selectedIndex]);
  if (!pending) return false;

  const validation = validatePendingDetailApplyRow(pending, gd);
  if (validation.status === 'REJECT' || validation.status === 'UNRESOLVED') {
    reportRuntimeFieldDefinitionValidationFailure(validation);
    return false;
  }

  finalizeValidatedDetailCommit(pending, selectedIndex);
  return true;
}

function applyDetail(e) {
  if (e) e.preventDefault();

  if (detailMode === 'new') {
    if (!draftRow || !Array.isArray(currentRows)) return;
    const pending = buildPendingDetailApplyRow(draftRow);
    if (!pending) return;

    // 反映直前にもNo/Keyを再採番して、開いている間に増えた行との重複を避ける。
    assignNewRowKeys(pending, pending);
    const validation = validatePendingDetailApplyRow(pending, gridDef());
    if (validation.status === 'REJECT' || validation.status === 'UNRESOLVED') {
      reportRuntimeFieldDefinitionValidationFailure(validation);
      return;
    }

    if (typeof getStudioJsonRoundTripDraftRow === 'function' && getStudioJsonRoundTripDraftRow()) {
      if (typeof discardStudioJsonRoundTripDraft === 'function') discardStudioJsonRoundTripDraft();
    }
    if (typeof markDetailSubGridEditsCommitted === 'function') markDetailSubGridEditsCommitted();
    clearRuntimeFieldDefinitionValidationMarks();

    currentRows.push(pending);
    selectedIndex = currentRows.length - 1;
    detailMode = 'edit';
    draftRow = null;
    applySearch();
    renderGrid();
    updateDetailNavButtons();
    setStatus('新規行を追加して詳細を反映しました');
    openDetail(selectedIndex, true);
    return;
  }

  if (selectedIndex < 0) return;
  const gd = gridDef();
  if (!tryCommitCurrentDetailEdits({ source: 'F12' })) return;
  renderGrid();
  // v0.18.46-definition-review-evidence:
  // F12 means Commit -> canonical Data -> full Detail rebind.
  // Standard fields and Derived Components must represent the same canonical point in time.
  rebindDetailAfterCanonicalCommit(currentRows[selectedIndex], { preserveScroll: true });
  setStatus('詳細を反映しました（F7/F8で前後移動できます）');
  // 承認作業では連続レビューしたいので、反映では詳細ダイアログを閉じない。
  // 閉じる場合は「閉じる」ボタンまたは右上×を使う。
}
function applyHeaderEdits() {
  const def = headerDef();
  if (def) {
    [...$('headerForm').querySelectorAll(
      'input[data-field], select[data-field], textarea[data-field], [data-markdown-display="true"][data-field]'
    )].forEach(inp => {
      const field = def.fields.find(f => f.field === inp.dataset.field);
      if (!field || field.edit?.readonly || field.readonly || inp.disabled) return;
      const fullPath = (def.dataPath === '$' ? '$.' : def.dataPath + '.') + field.field;
      const rawValue = typeof getControlValue === 'function' ? getControlValue(inp) : inp.value;
      // Sparse JSON preservation: ViewDefだけに存在する未設定optional fieldは、
      // untouchedな空UI値からDataへ空文字/false/nullを勝手に追加しない。
      if (typeof shouldSkipAbsentBlankWrite === 'function' && shouldSkipAbsentBlankWrite(sourceData, fullPath, rawValue)) return;
      setByPath(sourceData, fullPath, convertValue(field.type, rawValue));
    });
  }
  // v0.15.5.2: header-level Main Context panel edits belong to Data root,
  // not to ViewDef. Persist them whenever header edits are collected.
  if (typeof applyMainContextHeaderPanelEdits === 'function') {
    applyMainContextHeaderPanelEdits({ silent: true });
  }
}

function saveAsJson() {
  applyHeaderEdits();
  const blob = new Blob([JSON.stringify(sourceData, null, 2)], {type: 'application/json'});
  const a = document.createElement('a');
  const ts = typeof studioFormatFileTimestamp === 'function' ? studioFormatFileTimestamp() : new Date().toLocaleString('sv-SE').replace(/[-: ]/g, '').slice(0, 15);
  a.href = URL.createObjectURL(blob);
  a.download = `json_master_editor_saved_${ts}.json`;
  a.click();
  URL.revokeObjectURL(a.href);
}

function normalizeApiDataUrl(url) {
  if (!url) return null;
  try {
    const u = new URL(url, location.href);
    if (u.origin !== location.origin) return null;
    const prefix = '/api/data/';
    if (!u.pathname.startsWith(prefix)) return null;
    const rel = decodeURIComponent(u.pathname.slice(prefix.length));
    return safeJsonFileName(rel) ? u.pathname : null;
  } catch {
    return null;
  }
}


function normalizeWriteBackConfig(config) {
  const wb = config?.writeBack ?? config?.write_back;
  if (!wb || wb.enabled === false) return null;

  const source = wb.source ?? wb.dataSource ?? wb.data_source ?? '$current';
  const path = wb.path ?? wb.dataPath ?? wb.data_path ?? config?.axis?.path ?? config?.base?.path ?? '$';
  const keyField = wb.keyField ?? wb.key_field ?? config?.axis?.idField ?? config?.axis?.id_field ?? 'id';
  const rowKeyField = wb.rowKeyField ?? wb.row_key_field ?? keyField;
  const fields = normalizeWriteBackFields(wb.fields ?? wb.fieldMap ?? wb.field_map ?? []);

  if (!source || !path || !keyField || !rowKeyField || !fields.length) return null;
  return { source, path, keyField, rowKeyField, fields };
}

function normalizeWriteBackFields(fields) {
  if (Array.isArray(fields)) {
    return fields.map(item => {
      if (typeof item === 'string') return { from: item, to: item };
      if (item && typeof item === 'object') {
        const from = item.from ?? item.virtualField ?? item.virtual_field ?? item.field;
        const to = item.to ?? item.sourceField ?? item.source_field ?? item.field ?? from;
        return from && to ? { from, to } : null;
      }
      return null;
    }).filter(Boolean);
  }

  if (fields && typeof fields === 'object') {
    return Object.entries(fields).map(([from, to]) => ({ from, to: String(to || from) }));
  }

  return [];
}

function isCurrentSourceKey(key) {
  return !key || key === '$current' || key === 'current';
}

function dataSourceSpecByKey(key) {
  if (isCurrentSourceKey(key)) return null;
  return currentDataSourceSpecs[key] ?? currentDataSourceSpecs[String(key).replace(/-([a-z])/g, (_, c) => c.toUpperCase())] ?? null;
}

function dataSourceJsonByKey(key) {
  if (isCurrentSourceKey(key)) return sourceData;
  return currentDataSources[key] ?? currentDataSources[String(key).replace(/-([a-z])/g, (_, c) => c.toUpperCase())] ?? null;
}

function indexRowsByField(rows, field) {
  const map = new Map();
  normalizeArray(rows).forEach(row => {
    const key = String(getByPath(row, field) ?? '');
    if (key) map.set(key, row);
  });
  return map;
}

function applyVirtualRowsToWriteBackSource(config, wb) {
  const targetPath = virtualDataTargetPath(config);
  if (!targetPath) return { updated: 0, skipped: 0 };

  const virtualRows = getByPath(sourceData, targetPath);
  const sourceJson = dataSourceJsonByKey(wb.source);
  const sourceRows = getByPath(sourceJson, wb.path);
  if (!Array.isArray(virtualRows)) throw new Error(`writeBack対象の仮想データが配列ではありません: ${targetPath}`);
  if (!Array.isArray(sourceRows)) throw new Error(`writeBack source ${wb.source} の ${wb.path} が配列ではありません`);

  const sourceByKey = indexRowsByField(sourceRows, wb.keyField);
  let updated = 0;
  let skipped = 0;

  virtualRows.forEach(vrow => {
    const key = String(getByPath(vrow, wb.rowKeyField) ?? '');
    const sourceRow = sourceByKey.get(key);
    if (!key || !sourceRow) {
      skipped += 1;
      return;
    }

    wb.fields.forEach(({ from, to }) => {
      const value = getByPath(vrow, from);
      setByPath(sourceRow, to, cloneData(value));
    });
    updated += 1;
  });

  return { updated, skipped };
}

async function postDataSourceJsonByKey(key) {
  if (isCurrentSourceKey(key)) return null;
  const spec = dataSourceSpecByKey(key);
  const name = dataSourceFileName(spec);
  if (!name) throw new Error(`writeBack source「${key}」の保存先ファイル名を解決できません`);
  const url = apiJsonUrl('data', name);
  const json = dataSourceJsonByKey(key);
  const res = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(json)
  });
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`writeBack保存に失敗しました ${name} (${res.status}) ${text}`);
  }
  return { key, name, url };
}

async function writeBackVirtualDataEdits() {
  const configs = virtualDataArrayConfigOf(viewDef);
  if (!configs.length) return [];

  const touched = new Map();
  for (const config of configs) {
    const wb = normalizeWriteBackConfig(config);
    if (!wb) continue;
    const result = applyVirtualRowsToWriteBackSource(config, wb);
    const current = touched.get(wb.source) ?? { source: wb.source, updated: 0, skipped: 0 };
    current.updated += result.updated;
    current.skipped += result.skipped;
    touched.set(wb.source, current);
  }

  const saved = [];
  for (const item of touched.values()) {
    if (!item.updated) continue;
    const posted = await postDataSourceJsonByKey(item.source);
    saved.push({ ...item, ...(posted ?? { key: item.source, name: '(current)' }) });
  }
  return saved;
}

async function saveOverwriteJson() {
  applyHeaderEdits();
  // v0.18.58:
  // Row selection / ViewDef row-order operations can change selectedIndex while the
  // detail dialog is closed. The hidden detail form still contains the previously
  // opened row, so committing it here would merge stale values into the newly
  // selected row (for example __target_caption -> field_path).
  // Commit detail inputs on Save only while the detail dialog is actually open.
  const detailDialogOpen = Boolean($('detailDialog')?.open);
  if (detailMode === 'edit' && selectedIndex >= 0 && detailDialogOpen) {
    if (!tryCommitCurrentDetailEdits({ source: 'save' })) return false;
  }
  const systemAppSettingsMode = typeof isSystemAppSettingsMode === 'function' && isSystemAppSettingsMode();
  if (!systemAppSettingsMode && currentDataSourceKind !== 'viewdef') {
    ensureViewDefNameInData(sourceData, lastLoadedDefName || selectedDefName());
  }

  const writeBackSaved = await writeBackVirtualDataEdits();
  if (writeBackSaved.length) {
    const names = writeBackSaved.map(x => `${x.name}: ${x.updated}件`).join(' / ');
    setStatus(`主対象JSONを上書き保存しました: ${names}`);
    renderGrid();
    return;
  }

  if (!currentDataApiUrl) {
    setStatus('API読み込みではないため、別名保存します（上書き保存するには /api/data/xxx.json で読み込んでください）');
    saveAsJson();
    return true;
  }

  let saveDocument = (
    currentDataSourceKind === 'viewdef' &&
    typeof finalizeViewDefMaintenanceDocument === 'function' &&
    typeof isViewDefMaintenanceDocument === 'function' &&
    isViewDefMaintenanceDocument(sourceData)
  ) ? finalizeViewDefMaintenanceDocument(sourceData) : sourceData;

  if (systemAppSettingsMode) {
    if (typeof prepareSystemAppSettingsSaveDocument !== 'function') {
      throw new Error('App Settings保存契約が初期化されていません');
    }
    const prepared = prepareSystemAppSettingsSaveDocument(sourceData);
    if (!prepared?.ok) return false;
    saveDocument = prepared.document;
  }

  const res = await fetch(currentDataApiUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(saveDocument)
  });

  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new Error(`保存に失敗しました (${res.status}) ${text}`);
  }

  if (currentDataSourceKind === 'viewdef' && typeof invalidateDefinitionTargetViewDefCache === 'function') {
    invalidateDefinitionTargetViewDefCache(currentViewDefMaintenanceTarget || '');
  }
  if (systemAppSettingsMode && saveDocument?.updated_at) {
    sourceData.updated_at = saveDocument.updated_at;
  }
  if (systemAppSettingsMode && typeof window?.FrbStudioShell?.refreshLaunchShortcuts === 'function') {
    void window.FrbStudioShell.refreshLaunchShortcuts();
  }
  setStatus(`${systemAppSettingsMode ? 'Studio設定を' : (currentDataSourceKind === 'viewdef' ? 'ViewDefを' : '')}上書き保存しました: ${currentDataApiUrl}`);
  return true;
}

// v0.5-registry: high-level renderer registrations.
registerRenderer('detail', renderDetailForRow);
registerRenderer('childArea', renderChildArea);

